tags: [inotifypropertychanged, data-binding, mvvm, events]
code:
  language: csharp
  harness: statements
  source: |
    using System.ComponentModel;

    var vm = new OrderViewModel();
    vm.PropertyChanged += (_, e) => Console.WriteLine($"{e.PropertyName}: {vm.Status}");
    vm.Status = "Paid";
    vm.Status = "Shipped";

    class OrderViewModel : INotifyPropertyChanged
    {
        private string status = "New";

        public event PropertyChangedEventHandler PropertyChanged;

        public string Status
        {
            get => status;
            set
            {
                if (status == value)
                {
                    return;
                }

                OnPropertyChanged(nameof(Status));
                status = value;
            }
        }

        private void OnPropertyChanged(string propertyName) =>
            PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(propertyName));
    }
bugLineSets: [[24], [25], [24, 25]]
fixedSource: |
  using System.ComponentModel;

  var vm = new OrderViewModel();
  vm.PropertyChanged += (_, e) => Console.WriteLine($"{e.PropertyName}: {vm.Status}");
  vm.Status = "Paid";
  vm.Status = "Shipped";

  class OrderViewModel : INotifyPropertyChanged
  {
      private string status = "New";

      public event PropertyChangedEventHandler PropertyChanged;

      public string Status
      {
          get => status;
          set
          {
              if (status == value)
              {
                  return;
              }

              // Store the new value first, then notify: handlers re-read the property.
              status = value;
              OnPropertyChanged(nameof(Status));
          }
      }

      private void OnPropertyChanged(string propertyName) =>
          PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(propertyName));
  }
fixedExpect: { kind: output, value: "Status: Paid\nStatus: Shipped" }
